import json,subprocess,base64
from pathlib import Path
backup=Path('/opt/edgepulse/backups/paper-growth-20261118-113416')
probe='import importlib.metadata as m,json; print(json.dumps({d.metadata["Name"]:d.version for d in m.distributions()},sort_keys=True))'
a=json.loads((backup/'dependencies-before.json').read_text())
b=json.loads(subprocess.check_output(['docker','run','--rm','--network','none','--entrypoint','python','edgepulse:paper','-c',probe]))
diff={k:{'before':a.get(k),'after':b.get(k)} for k in a.keys()|b.keys() if a.get(k)!=b.get(k)}
print('dependency changes',json.dumps(diff));assert not diff,'runtime dependency drift'
f=backup/'test_paper_growth.py';f.write_bytes(base64.b64decode(''));f.chmod(0o644)
r=subprocess.run(['docker','run','--rm','--network','none','--read-only','--tmpfs','/tmp:mode=1777','--mount','type=bind,source='+str(f)+',target=/tmp/test_paper_growth.py,readonly','--entrypoint','python','edgepulse:paper','/tmp/test_paper_growth.py'],text=True,capture_output=True)
print(r.stdout);print(r.stderr);assert r.returncode==0,'container tests failed'
print('container feature tests passed')
